import {Lab,defaults,policyNames,policyHints,compare} from './model.mjs';
const $=id=>document.getElementById(id);
const format=n=>Math.abs(n)<.05?'0':Number(n.toFixed(1)).toLocaleString();
const percent=n=>format(n*100)+'%';
const clock=n=>'00:'+String(n).padStart(2,'0');
let lab=new Lab(), timer=null, quizIndex=0,tourIndex=0,tourActive=false;
const terms={
slo:{name:'SLO · Service Level Objective',tag:'THE PROMISE',meaning:'A measurable reliability goal for users. It says how often the application should work well over a declared period.',example:'“At least 99 out of every 100 requests should succeed.” That is a 99% availability SLO.',cep:'Your CEP watches two goals separately: successful requests and responses within 500ms.'},
sli:{name:'SLI · Service Level Indicator',tag:'THE MEASUREMENT',meaning:'The measurement that tells us whether the promise is being kept. An SLO is the target; an SLI is what actually happened.',example:'Target: 99% successful. Measured: 985 successful requests out of 1,000 = 98.5%.',cep:'Client outcomes classify successful, failed, and slow requests. A timeout is a failure even if a server later finishes.'},
budget:{name:'Error budget',tag:'THE ALLOWANCE',meaning:'The amount of imperfect service your goal allows. It is an allowance for bad requests, not a sum of money.',example:'At 99% success, 1,000 requests allow 10 failures. If 4 fail, 6 remain.',cep:'Each experiment receives a fixed share of a declared budget. Availability and latency budgets are independent; do not add them together.'},
availability:{name:'Availability',tag:'DID IT WORK?',meaning:'The share of eligible requests that succeed. A failed connection, timeout, or server error can count as a failed request.',example:'If 990 of 1,000 requests succeed, availability is 99%.',cep:'Injected HTTP 503 errors consume availability budget. Slow but successful responses do not, unless they time out.'},
latency:{name:'Latency',tag:'HOW LONG DID IT TAKE?',meaning:'The time a request takes. The latency SLO counts requests that finish within a threshold.',example:'A 650ms response is too slow for a 500ms goal, even if it succeeds.',cep:'Your conservative latency definition also counts failures as bad. One failed request may therefore consume both SLO budgets; this is not double counting within a single budget.'},
burn:{name:'Burn rate',tag:'HOW FAST ARE WE SPENDING?',meaning:'The actual bad-request fraction divided by the fraction the SLO permits. It is a rate, not the number of requests already spent.',example:'99% success permits 1% failures. If 5% fail, burn is 5 ÷ 1 = 5×. At 1×, a matching traffic mix uses the allowed fraction.',cep:'Short and long observation windows help the real controller see recent and sustained pressure. This learning model simplifies those windows.'},
chaos:{name:'Chaos engineering',tag:'A CONTROLLED FIRE DRILL',meaning:'Intentionally introducing a small failure to learn how a system behaves under stress, with a hypothesis and clear stopping rules.',example:'Slow one dependency and check whether the user-facing application still meets its goal.',cep:'Your contribution is studying how budget feedback could control the intensity of the drill.'},
fault:{name:'Fault injection',tag:'THE THING WE BREAK ON PURPOSE',meaning:'Deliberately making a component fail or respond slowly. Fault intensity is how many requests, or how much of a resource, we affect.',example:'An 8% delay fault means roughly 8 out of 100 matching requests get an added delay.',cep:'Istio applies delay or abort rules to the treatment dependency. This page only samples imaginary outcomes.'},
control:{name:'Control copy',tag:'THE COMPARISON GROUP',meaning:'A matching application copy that does not receive the intentional fault. It shows what might have happened without the experiment.',example:'If the normal copy has 2 failures and the test copy has 7 out of the same request count, the extra 5 may be related to the fault.',cep:'Real copies can share a node or other resources. If our fault damages the control too, this comparison can become misleading.'},
treatment:{name:'Treatment copy',tag:'THE EXPERIMENT GROUP',meaning:'The application copy that receives our intentional fault, while serving a comparable workload.',example:'We inject a delay into the test copy’s dependency while leaving the control dependency alone.',cep:'The prototype uses separate services and pods. Comparable traffic and resource isolation are conditions for credible attribution.'},
attribution:{name:'Attribution',tag:'WHICH FAILURES WERE OURS?',meaning:'Estimating how much additional damage the experiment caused, rather than blaming it for problems that already existed.',example:'With 100 requests per copy: 7 test failures − 2 control failures = 5 estimated extra failures.',cep:'When request counts differ: test failures − test request count × control failure rate. This is an estimate, not proof of causality. Random sampling may even produce a negative estimate.'},
controller:{name:'Closed-loop controller',tag:'LOOK → DECIDE → ADJUST',meaning:'A decision-maker that measures what happened, changes the fault, and measures again. “Closed loop” means feedback returns to the next decision.',example:'A person turning a tap down when a bucket is nearly full, rather than leaving the tap fixed.',cep:'The candidate controller increases slowly, decreases faster under pressure, and stops at safety boundaries. This page uses a simplified teaching version.'},
accountant:{name:'Budget Accountant',tag:'KEEP THE SCORE',meaning:'The component that tracks the independent SLO allowances, spending, and burn rates.',example:'Availability: 6 failures left. Latency: 28 slow-or-failed requests left.',cep:'The Python prototype maintains fixed count-based ledgers. Its service budget comes from declared expected requests; it is not a verified 30-day production budget.'},
oracle:{name:'Budget Oracle',tag:'WHAT DID WE LEARN?',meaning:'A summary of how much budget a completed test consumed per unit of fault exposure.',example:'A test exposed the system to 2 fraction-seconds of faults and estimated 20 extra failures: descriptive cost = 10 failures per fraction-second.',cep:'The current oracle is descriptive. It does not guarantee what a future run will cost.'},
reserve:{name:'Safety reserve',tag:'LEAVE ROOM TO STOP',meaning:'A portion of the allowance kept unused because faults do not disappear instantly after a stop decision.',example:'At up to 100 requests/s and 2 seconds of stopping delay, as many as 200 requests could be affected.',cep:'The prototype reserves max requests/s × declared lag/removal seconds, assuming every request in that interval could be bad. If it cannot fit, admission should be rejected.'},
watchdog:{name:'Watchdog',tag:'THE SEPARATE SAFETY HELPER',meaning:'An independent process that can remove an expired fault even if the main controller crashes.',example:'The fire drill supervisor disappears, but a second person still turns the alarm off.',cep:'Istio has no built-in fault TTL here. The watchdog needs a working Kubernetes API to remove the fault; this is not an unconditional guarantee.'},
traffic:{name:'Traffic · requests per second',tag:'HOW BUSY IS THE APP?',meaning:'A request is one attempt to use the application. Requests per second (RPS) describe how much work arrives.',example:'100 RPS means about 100 attempts every second, such as opening product pages.',cep:'Traffic changes can affect both reliability and how quickly a fixed allowance is spent. This lab freezes the allowance at admission.'},
microservice:{name:'Microservice & dependency',tag:'SMALL PARTS WORKING TOGETHER',meaning:'A microservice is one small application component. A dependency is another component it needs to finish its job.',example:'A shop frontend calls a product service to display an item. If that service slows, the user may wait.',cep:'The prototype has a frontend and dependency per cohort. The fault is applied to the treatment dependency.'},
kubernetes:{name:'Kubernetes',tag:'THE CONTAINER ORGANIZER',meaning:'A platform that runs and manages application containers, including restarting them and connecting them.',example:'Think of a building manager assigning rooms to services and checking that they stay alive.',cep:'The disposable kind cluster is a local Kubernetes lab. A namespace scopes the CEP resources; this visualizer runs without it.'},
istio:{name:'Istio',tag:'THE TRAFFIC MIDDLE LAYER',meaning:'Infrastructure that can manage communication between services. It can also apply controlled delays and errors.',example:'An adjustable checkpoint between the frontend and dependency adds 600ms to selected requests.',cep:'The adapter edits a specific treatment VirtualService. Kubernetes API acknowledgment does not prove the rule has reached every proxy yet.'},
prometheus:{name:'Prometheus & Grafana',tag:'MEASUREMENTS & DASHBOARDS',meaning:'Prometheus collects metrics; Grafana displays them in dashboards.',example:'A thermometer takes readings. A screen draws those readings over time.',cep:'The prototype uses client-side k6 outcomes for exact event accounting. Prometheus server metrics support inspection, rather than replacing missing client failures.'},
exposure:{name:'Fault exposure',tag:'HOW MUCH TESTING DID WE DO?',meaning:'Intensity multiplied by time, added over the run. It helps distinguish useful testing from simply stopping immediately.',example:'10% intensity for 20 seconds = 0.1 × 20 = 2 fraction-seconds.',cep:'Delay magnitude is held fixed. In the real prototype, commanded exposure has uncertainty because mesh propagation takes time.'},
policy:{name:'Policy',tag:'THE RULE FOR DECISIONS',meaning:'A strategy for choosing fault intensity and deciding when to stop.',example:'Fixed: leave it alone. Threshold: stop at a warning line. Preplanned: choose once. Adaptive: keep adjusting.',cep:'Comparisons should use the same workload, allowance, bounds, and emergency guards. One synthetic run cannot establish a winner.'},
uncertainty:{name:'Wilson uncertainty screen',tag:'CAUTION HAS A COST',meaning:'A formula that allows for uncertainty in a measured failure rate. Observing zero failures does not prove the true failure probability is zero.',example:'For 200 perfectly healthy requests, the prototype’s treatment upper bound still charges about 3.77 requests when compared with a healthy control lower bound.',cep:'Summing this estimate every interval can exhaust the allowance with no actual failures. It is not a time-uniform confidence guarantee. The lab can reproduce this behavior.'},
p99:{name:'p99 · tail latency',tag:'THE SLOW END OF THE QUEUE',meaning:'The response time below which about 99% of observed requests fall. It describes the slowest part of the distribution.',example:'A p99 of 800ms suggests around 1% of observed requests are at or above that neighborhood, depending on estimation.',cep:'A percentile is not a request count. Budget arithmetic should count requests exceeding the SLO threshold, not subtract p99 milliseconds from a budget.'},
contamination:{name:'Control contamination',tag:'WHEN THE COMPARISON IS UNFAIR',meaning:'The fault also affects the supposedly unaffected control, or the groups differ in important ways.',example:'Both app copies share a database. Breaking it for the test copy makes the control slow too, hiding some damage.',cep:'A recent isolation check helps but cannot establish continuous causal validity. Background-error experiments and negative controls remain research gates.'}
};
const stories={
gentle:{family:'delay',limit:.08,background:0,screen:false,title:'A slowdown is not always an outage.',copy:'The delayed requests may still succeed. That leaves availability untouched, but responses over 500ms spend the latency budget. Watch the two ledgers move independently.'},
outage:{family:'abort',limit:.12,background:0,screen:false,title:'A failed request affects both promises.',copy:'An injected HTTP 503 means the request did not work. Your conservative latency definition counts that failure as bad too. The controller must respect both separate allowances.'},
background:{family:'abort',limit:.06,background:.005,screen:false,title:'Not every failure belongs to the experiment.',copy:'Both copies can fail naturally. Attribution compares their bad-request rates to estimate the extra damage from our fault. Because these are random samples, the estimate can be noisy.'},
uncertainty:{family:'abort',limit:0,background:0,screen:true,title:'Zero actual failures. A shrinking enforcement budget.',copy:'The repository adds a conservative Wilson estimate every interval. Even with perfectly healthy requests, that estimate is positive. Compare actual failures with charged budget: caution can stop the test without finding a weakness.'}
};
function configFromUI(){return{policy:$('policy').value,family:$('family').value,limit:+$('intensity').value/100,rps:+$('rps').value,background:+$('background').value/100,target:+$('target').value,share:+$('allocation').value,reserveSeconds:+$('reserve').value,screen:$('screen').checked};}
function syncUI(config){$('policy').value=config.policy;$('family').value=config.family;$('intensity').value=Math.round(config.limit*100);$('rps').value=config.rps;$('background').value=Number((config.background*100).toFixed(1));for(const [id,value] of [['target',config.target],['allocation',config.share],['reserve',config.reserveSeconds]])$(id).value=[...$(id).options].find(o=>Number(o.value)===value).value;$('screen').checked=config.screen;updateLabels();}
function updateLabels(){$('intensity-out').textContent=$('intensity').value+'%';$('rps-out').textContent=$('rps').value+' req/s';$('background-out').textContent=$('background').value+'%';$('policy-hint').textContent=policyHints[$('policy').value];$('traffic-label').textContent=$('rps').value+' requests/s each';$('fault-label').textContent=$('family').value==='delay'?'Delay some requests':'Fail some requests';}
function pause(){clearInterval(timer);timer=null;lab.running=false;}
function reset(){pause();lab=new Lab(configFromUI());render();}
function start(){if(lab.status==='STOPPED'||lab.status==='REJECTED'){reset();}if(!lab.admit()){render();announce(lab.reason);return;}lab.running=true;timer=setInterval(()=>{lab.step();if(lab.status!=='RUNNING')pause();render();},650);render();}
function announce(s){$('announcement').textContent=s;}
function fmtTime(t){return t===60?'01:00':clock(t);}
function render(){updateLabels();$('clock').textContent=fmtTime(lab.time);$('play').innerHTML=timer?'Ⅱ &nbsp; Pause':lab.status==='STOPPED'||lab.status==='REJECTED'?'↺ &nbsp; Replay experiment':'▶ &nbsp; Play experiment';$('step').disabled=['STOPPED','REJECTED'].includes(lab.status);$('state-badge').textContent=lab.status==='READY'?'READY TO EXPLORE':lab.status==='RUNNING'?(timer?'EXPERIMENT RUNNING':'PAUSED · STEP TO EXPLORE'):lab.status==='REJECTED'?'ADMISSION REJECTED':'EXPERIMENT STOPPED';$('state-badge').className='badge '+(['STOPPED','REJECTED'].includes(lab.status)?'stop':timer?'warn':'mint');document.querySelector('.topology').classList.toggle('running',!!timer);
const c=lab.last?.counts.control,t=lab.last?.counts.treatment;$('control-result').textContent=(c?.availability||0)+' failed';$('test-result').textContent=((lab.config.family==='delay'?t?.latency:t?.availability)||0)+' affected';$('control-health').textContent=c?.availability?c.availability+' natural failures':'Healthy baseline';
for(const [name,prefix] of [['availability','a'],['latency','l']]){const l=lab.ledgers[name],left=Math.max(0,l.allocation-l.charged),pct=Math.max(0,100*left/l.allocation);$(prefix+'-remaining').textContent=format(left);$(prefix+'-percent').textContent=format(pct)+'%';$(prefix+'-meter').style.width=pct+'%';$(prefix+'-spent').textContent=format(l.charged)+' / '+format(l.allocation)+' spent';} $('a-target').textContent=percent(lab.config.target)+' successful';
$('actual-intensity').textContent=percent(lab.last?.applied||0);$('control-bad').textContent=c?.availability||0;$('treatment-bad').textContent=t?.availability||0;$('attributed-bad').textContent=format(lab.last?.estimates.availability.signed||0);$('burn-rate').textContent=format(lab.last?.burns.availability||0)+'×';$('reserve-caption').textContent=format(lab.reserve)+' bad requests reserved for stopping. Allocation is '+(lab.config.screen?'Wilson-screen charged.':'point-estimate charged.');
const header=document.querySelector('.controller-band b');header.textContent=lab.status==='READY'?'The controller is waiting.':lab.status==='REJECTED'?'The experiment cannot start safely.':lab.status==='STOPPED'?'The controller stopped the experiment.':timer?'Watching the budget. Adjusting the fault.':'Paused. Take your time.';
$('decision').textContent=lab.reason||(!lab.time?'Press Play to send traffic and start the experiment.':policyNames[lab.config.policy]+': next fault '+percent(lab.intensity)+'. '+(lab.config.screen?'Uncertainty-screen estimates are charged.':'Estimated extra bad requests are charged.'));
$('event-log').replaceChildren(...(lab.events.length?lab.events:[{time:0,message:'Ready. Choose a story or press play.'}]).slice(0,12).map(e=>{const li=document.createElement('li'),span=document.createElement('span');span.textContent=fmtTime(e.time);li.append(span,document.createTextNode(e.message));return li;}));renderChart();renderMath();}
function renderChart(){const w=620,h=126,x0=38,y0=15;let svg='';for(const v of [0,25,50,75,100]){const y=y0+h*(1-v/100);svg+='<line x1="'+x0+'" y1="'+y+'" x2="658" y2="'+y+'" stroke="#edf0ed" stroke-dasharray="3 4"/><text x="27" y="'+(y+3)+'" text-anchor="end" fill="#a9b1ad" font-size="9">'+v+'%</text>';}for(const s of [0,15,30,45,60]){const x=x0+w*s/60;svg+='<text x="'+x+'" y="166" text-anchor="middle" fill="#a9b1ad" font-size="9">'+s+'s</text>';}for(const v of [0,15,30])svg+='<text x="667" y="'+(y0+h*(1-v/30)+3)+'" fill="#c7a88e" font-size="8">'+v+'%</text>';
const points=[{time:0,a:100,l:100,intensity:0},...lab.history];for(const [key,color]of[['a','#7da98e'],['l','#8aa5ce'],['intensity','#d49868']]){const p=points.map(d=>(x0+w*d.time/60)+','+(y0+h*(1-(key==='intensity'?d[key]/30:d[key]/100)))).join(' ');svg+='<polyline points="'+p+'" fill="none" stroke="'+color+'" stroke-width="2" stroke-linejoin="round" '+(key==='intensity'?'stroke-dasharray="4 3"':'')+'/>';}if(!lab.time)svg+='<text x="350" y="81" text-anchor="middle" fill="#b2bbb5" font-size="10">Your experiment will appear here. Press Play or Step.</text>';$('chart').innerHTML=svg;
if(!$('chart-table').hidden){$('chart-table').innerHTML='<table><caption>Sampled learning run</caption><thead><tr><th>Second</th><th>Availability left</th><th>Latency left</th><th>Fault</th></tr></thead><tbody>'+lab.history.map(p=>'<tr><td>'+p.time+'</td><td>'+format(p.a)+'%</td><td>'+format(p.l)+'%</td><td>'+format(p.intensity)+'%</td></tr>').join('')+'</tbody></table>';}}
function renderMath(){const l=lab.ledgers.availability;$('math-detail').innerHTML='<p>Declared reservation: '+lab.reservedRps+' requests/s × 120s = <b>'+lab.expected.toLocaleString()+' expected requests</b>.</p><p>Allowed failures: <code>'+format(100*(1-lab.config.target))+'% × '+lab.expected+' = '+format(l.q*lab.expected)+'</code>.</p><p>Experiment share: <code>'+format(lab.config.share*100)+'% × '+format(l.q*lab.expected)+' = '+format(l.allocation)+' bad requests</code>.</p><p>Stopping reserve: <code>'+lab.reservedRps+' × '+lab.config.reserveSeconds+'s = '+format(lab.reserve)+'</code>.</p><p>Last-interval burn: <code>observed failure fraction ÷ allowed failure fraction = '+format(lab.last?.burns.availability||0)+'×</code>.</p><p>Actual total test failures: <b>'+l.totalBad+'</b>. Signed estimated extra: <b>'+format(l.signed)+'</b>. Enforcement charge: <b>'+format(l.charged)+'</b>. These are different quantities.</p>';}
function showTerm(key){const t=terms[key];if(!t)return;tourActive=false;$('dialog-label').textContent=t.tag;$('dialog-title').textContent=t.name;$('dialog-body').innerHTML='<p>'+t.meaning+'</p><div class="example">'+t.example+'</div><p><b>In your CEP:</b> '+t.cep+'</p>';$('dialog-done').textContent='Got it →';if(!$('term-dialog').open)$('term-dialog').showModal();}
function showView(name){if(!['sandbox','journey','compare','glossary'].includes(name))name='sandbox';pause();document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.view===name);if(el.dataset.view===name)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});history.replaceState(null,'','#'+name);window.scrollTo({top:0,behavior:'instant'});render();}
document.addEventListener('click',e=>{const term=e.target.closest('[data-term]');if(term)showTerm(term.dataset.term);const view=e.target.closest('[data-view]');if(view)showView(view.dataset.view);const story=e.target.closest('[data-scenario]');if(story){const s=stories[story.dataset.scenario];syncUI({...defaults,...s});$('lesson-title').textContent=s.title;$('lesson-copy').textContent=s.copy;document.querySelectorAll('.scenario').forEach(b=>b.classList.toggle('active',b===story));reset();}});
$('play').onclick=()=>{if(timer){pause();render();}else start();};$('step').onclick=()=>{pause();lab.step();render();};$('reset').onclick=reset;
for(const id of ['intensity','rps','background'])$(id).addEventListener('input',()=>{if(lab.status==='READY')lab=new Lab(configFromUI());else lab.config={...lab.config,...configFromUI()};updateLabels();render();});
for(const id of ['policy','family','target','allocation','reserve','screen'])$(id).addEventListener('change',reset);
$('math-toggle').onclick=()=>{const hidden=$('math-detail').hidden;$('math-detail').hidden=!hidden;$('math-toggle').setAttribute('aria-expanded',hidden);$('math-toggle').textContent=hidden?'Hide the maths ↑':'Show me the maths ↓';};
$('chart-table-toggle').onclick=()=>{const hidden=$('chart-table').hidden;$('chart-table').hidden=!hidden;$('chart-table-toggle').setAttribute('aria-expanded',hidden);$('chart-table-toggle').textContent=hidden?'Hide numbers':'View numbers';renderChart();};
$('export').onclick=()=>{const data={type:'teaching-simulation-not-research-evidence',model:'seeded-learning-v1',config:lab.config,reservedRps:lab.reservedRps,declaredReservationSeconds:120,expected:lab.expected,reserve:lab.reserve,status:lab.status,reason:lab.reason,ledgers:lab.ledgers,history:lab.history,events:lab.events,exposure:lab.exposure};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='chaos-lab-learning-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('close-dialog').onclick=()=>$('term-dialog').close();$('term-dialog').addEventListener('click',e=>{if(e.target===$('term-dialog')){const r=$('term-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('term-dialog').close();}});
const tours=[['Meet the two copies','The control copy runs normally. The test copy receives our intentional fault. Click any box to learn what it does.'],['Choose what goes wrong','Try a slowdown first. A delayed request can succeed, so watch latency spend while availability stays healthy.'],['Watch the allowance','Each SLO has its own budget. The experiment gets only a share, and some must remain in reserve while stopping.'],['Listen to the controller','Press Play or Step. The notebook explains why intensity changes. Then compare policies or try the “Healthy, but budget spent?” story.']];
function showTour(){tourActive=true;const t=tours[tourIndex];$('dialog-label').textContent='QUICK TOUR · '+(tourIndex+1)+' OF 4';$('dialog-title').textContent=t[0];$('dialog-body').innerHTML='<p>'+t[1]+'</p>';$('dialog-done').textContent=tourIndex===3?'Start exploring →':'Next step →';if(!$('term-dialog').open)$('term-dialog').showModal();}
$('tour-button').onclick=$('explain-button').onclick=()=>{pause();render();tourIndex=0;showTour();};$('dialog-done').onclick=()=>{if(tourActive&&tourIndex<3){tourIndex++;showTour();}else{$('term-dialog').close();tourActive=false;}};
const journeys=[['Make a promise','“Most requests should succeed and finish quickly.” Define two measurable SLOs before running a test.','slo','SLO = what good service means'],['Set an allowance','Perfect reliability is rarely the target. Convert the allowed bad fraction into a request budget and give the experiment a share.','budget','Error budget = room for imperfection'],['Keep a normal copy','Send comparable traffic to the control and test copies. Add a fault only to the test copy’s dependency.','control','Control = a reference for comparison'],['Separate the damage','Compare bad-request rates. Try to distinguish fault-induced damage from problems that already existed.','attribution','Attribution = estimating our extra damage'],['Adjust, then check again','Use the remaining allowances to decide whether to increase, reduce, or stop the fault. Keep a separate watchdog.','controller','Feedback = observe → decide → adjust'],['Learn from the cost','Measure damage and exposure across repeated tests. A system that stops immediately can be safe but reveal little.','oracle','Oracle = a descriptive cost summary']];
$('journey-cards').innerHTML=journeys.map((j,i)=>'<article class="panel journey-card"><span class="step-number">0'+(i+1)+' /</span><h2>'+j[0]+'</h2><p>'+j[1]+'</p><small>'+j[3]+'</small><button class="text-button" data-term="'+j[2]+'">Explain the term ↗</button></article>').join('');
$('tools-map').innerHTML=[['Kubernetes','Runs the two application copies in a disposable cluster.'],['Istio','Adds controlled delays or HTTP errors to matching traffic.'],['k6','Sends requests and records what the client experienced.'],['Prometheus','Collects supporting server metrics.'],['Grafana','Displays the measurements in dashboards.'],['Python controller','Tracks budgets and decides what the fault should do next.']].map(([n,d])=>'<div><b>'+n+'</b><p>'+d+'</p></div>').join('');
function renderGlossary(){const q=$('glossary-search').value.toLowerCase().trim(),entries=Object.entries(terms).filter(([k,t])=>(k+' '+Object.values(t).join(' ')).toLowerCase().includes(q));$('glossary-grid').innerHTML=entries.map(([k,t])=>'<article class="panel glossary-card"><span class="term-tag">'+t.tag+'</span><h2>'+t.name+'</h2><p>'+t.meaning+'</p><div class="example">'+t.example+'</div><button class="text-button" data-term="'+k+'">Connect it to our CEP ↗</button></article>').join('');$('glossary-empty').hidden=!!entries.length;}
$('glossary-search').addEventListener('input',renderGlossary);
const quizzes=[{q:'A request succeeds, but takes 800ms. Which budget does it spend?',a:['Availability only','Latency only','Neither'],correct:1,why:'It worked, so availability is fine. It exceeded the 500ms threshold, so it spends latency budget.'},{q:'Out of 100 requests each, control has 2 failures and test has 7. What is estimated extra damage?',a:['7 failures','9 failures','5 failures'],correct:2,why:'7 − 2 = 5 estimated extra failures. The comparison adjusts for background problems; it is still an estimate.'},{q:'With a 99% success goal, a 5% failure rate has what burn rate?',a:['5×','0.05×','99×'],correct:0,why:'The SLO permits 1% failures. Actual 5% divided by allowed 1% gives a 5× burn rate.'},{q:'Why keep a separate watchdog?',a:['To increase the budget','To remove a fault if the controller disappears','To make every request succeed'],correct:1,why:'The watchdog is an independent cleanup helper. It still needs the infrastructure/API to be reachable.'}];
function renderQuiz(){const q=quizzes[quizIndex];$('quiz-question').textContent=q.q;$('quiz-feedback').textContent='';$('quiz-options').replaceChildren(...q.a.map((answer,i)=>{const button=document.createElement('button');button.textContent=answer;button.onclick=()=>{document.querySelectorAll('#quiz-options button').forEach(b=>{b.disabled=true;});button.className=i===q.correct?'correct':'wrong';$('quiz-options').children[q.correct].classList.add('correct');$('quiz-feedback').textContent=(i===q.correct?'Exactly. ':'Almost. ')+q.why;};return button;}));}
$('next-quiz').onclick=()=>{quizIndex=(quizIndex+1)%quizzes.length;renderQuiz();};
$('run-comparison').onclick=()=>{const runs=compare(configFromUI());$('comparison-results').innerHTML=runs.map(run=>{const a=run.ledgers.availability,l=run.ledgers.latency;return '<article class="panel comparison-card"><div class="eyebrow">'+run.config.policy.toUpperCase()+'</div><h2>'+policyNames[run.config.policy]+'</h2><p>'+policyHints[run.config.policy]+'</p><dl><div><dt>Seconds tested</dt><dd>'+run.time+' / 60</dd></div><div><dt>Availability charge / allocation</dt><dd>'+format(a.charged)+' / '+format(a.allocation)+'</dd></div><div><dt>Latency charge / allocation</dt><dd>'+format(l.charged)+' / '+format(l.allocation)+'</dd></div><div><dt>Largest charge overshoot</dt><dd>'+format(Math.max(0,a.charged-a.allocation,l.charged-l.allocation))+' requests</dd></div><div><dt>Fault exposure</dt><dd>'+format(run.exposure)+' fraction-s</dd></div><div><dt>Actual test-copy failures</dt><dd>'+a.totalBad+'</dd></div></dl><small>'+run.reason+'</small></article>';}).join('');announce('Comparison complete. Four synthetic policy runs are displayed.');};
renderGlossary();renderQuiz();render();showView(location.hash.slice(1)||'sandbox');

